def compute(vars):
    x0 = vars["Revenue"]
    x1 = vars["Cost of Sales"]
    gross_profit = x0 - x1

    return {
        "value": gross_profit,
        "trace": {
            "Revenue": x0,
            "Cost of Sales": x1,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
